mapper.sql:
from sys_team t


        and t.team_name like concat('%', #{teamName}, '%')


        and t.plan_id = #{planId}

mapper.select:
select t.team_id, t.team_name, t.team_key, t.team_icon, t.create_by, t.create_time, t.update_by, t.update_time, t.introduce, t.is_del, t.is_lock, t.lock_remark, t.plan_id, pl.plan_name, IFNULL(p.project_count, 0) as project_count, IFNULL(m.member_count, 0) as member_count from sys_team t LEFT JOIN sys_team_plan pl ON pl.plan_id = t.plan_id LEFT JOIN ( select count(team_id) as project_count, team_id from sys_project group by team_id ) p ON p.team_id = t.team_id LEFT JOIN ( select count(team_id) as member_count, team_id from sys_user_team where team_lock = 0 group by team_id ) m ON m.team_id = t.team_id
and t.team_name like concat('%', #{teamName}, '%')
and t.plan_id = #{planId}
order by t.team_id limit #{limit} offset #{offset}

mapper.sql:
from sys_team t
where (t.is_del != 1 OR t.is_del IS NULL)
  and (
    exists (
        select 1 from sys_user_team ut
        where ut.team_id = t.team_id and ut.user_id = #{userId}
    )
    or exists (
        select 1
        from sys_project p
        inner join sys_user_project up on up.project_id = p.project_id and up.user_id = #{userId}
        where p.team_id = t.team_id and p.project_state > 0
    )
  )

mapper.select:
select t.team_id, t.team_name, t.team_key, t.team_icon, t.create_by, t.create_time, t.update_by, t.update_time,
       t.introduce, t.is_del, t.is_lock, t.lock_remark,
       (exists (
           select 1 from sys_user_team ut
           where ut.team_id = t.team_id and ut.user_id = #{userId}
       )) as formal_member

order by formal_member desc, t.team_id
limit #{limit} offset #{offset}

mapper.update:
update sys_team
team_name = #{teamName}, team_key = #{teamKey}, team_icon = #{teamIcon}, update_by = #{updateBy}, update_time = #{updateTime}, introduce = #{introduce}, is_lock = #{lock}, lock_remark = #{lockRemark}, defect_builtin_field_config = #{defectBuiltinFieldConfig}, defect_page_config = #{defectPageConfig}, module_page_config = #{modulePageConfig}, case_review_template = #{caseReviewTemplate}, plan_id = #{planId},
where team_id = #{teamId}

mapper.select:
select user_team_id
from sys_user_team
where user_id = #{userId}
  and team_id = #{teamId}
order by user_team_id desc
limit 1
